const dsrOpen=d=>d.status!=='Completed'&&d.status!=='Rejected',dsrLate=d=>dsrOpen(d)&&dTo(d.due)<0;
const brClocks=b=>b.regimes.filter(r=>REG_H[r]).map(r=>({r,h:hLeft(b.detected,REG_H[r]),done:b.notified[r]||''}));
const brOpenClocks=b=>b.status==='Closed'?[]:brClocks(b).filter(c=>!c.done);
